package com.ruoyi.web.controller.projectmanagement;
import com.ruoyi.common.core.controller.BaseController;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.projectmanagement.execution.domain.LifecycleActionRequest;import com.ruoyi.projectmanagement.phase.domain.ProjectPhase;import com.ruoyi.projectmanagement.phase.service.IProjectPhaseService;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/projectManagement/phase") public class ProjectPhaseController extends BaseController {private final IProjectPhaseService service;public ProjectPhaseController(IProjectPhaseService s){service=s;}@GetMapping("/list")public AjaxResult list(ProjectPhase p){return success(service.list(p));}@GetMapping("/{id}")public AjaxResult get(@PathVariable Long id){return success(service.get(id));}@PostMapping public AjaxResult add(@Validated @RequestBody ProjectPhase p){return toAjax(service.add(p,getUsername()));}@PutMapping public AjaxResult edit(@Validated @RequestBody ProjectPhase p){return toAjax(service.edit(p,getUsername()));}@DeleteMapping("/{id}")public AjaxResult remove(@PathVariable Long id){return toAjax(service.remove(id,getUsername()));}@PostMapping("/{id}/lifecycle")public AjaxResult lifecycle(@PathVariable Long id,@RequestBody LifecycleActionRequest r){return toAjax(service.lifecycle(id,r.getAction(),getUsername()));}}
